<script setup lang="ts">
import { computed, ref } from "vue";
import { ElButton, ElInput, ElDialog, ElCheckbox, ElMessage, ElMessageBox } from "element-plus";
import { request } from "../../shared/api";
import { message, type RemoteHost, type Diagnostic } from "./types";
import { useUnsaved } from "./unsaved";
const props=defineProps<{base:string;connection:RemoteHost;etag:string}>();
const emit=defineEmits<{saved:[RemoteHost,string]}>();
const keys=computed(()=>props.connection.config?.host_keys??[]);
const busy=ref(false), error=ref(""), dialog=ref(false), candidate=ref(""), fingerprint=ref(""), confirmed=ref(false), capturedTag=ref(""), probing=ref(false);
const fingerprints=computed(()=>props.connection.host_key_fingerprints??{});
function manual(){candidate.value="";fingerprint.value="";confirmed.value=false;capturedTag.value=props.etag;probing.value=false;error.value="";dialog.value=true;}
async function probe(){busy.value=true;error.value="";const tag=props.etag;try{const d=(await request<Diagnostic>(props.base+"/test",{method:"POST",etag:tag,body:{}})).data;if(!d.summary.host_key)throw new Error("未取得主机公钥，请检查地址、端口与网络");candidate.value=d.summary.host_key;fingerprint.value=d.summary.fingerprint??"";confirmed.value=false;capturedTag.value=tag;probing.value=true;dialog.value=true;}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function persist(next:string[],etag:string){const r=await request<RemoteHost>(props.base,{method:"PATCH",etag,body:{config:{host_keys:next}}});emit("saved",r.data,r.etag);ElMessage.success("主机公钥已更新");}
async function save(){if(!confirmed.value||busy.value)return;busy.value=true;error.value="";try{if(!candidate.value.trim())throw new Error("请输入主机公钥");if(keys.value.includes(candidate.value.trim()))throw new Error("该公钥已受信任");await persist([...keys.value,candidate.value.trim()],capturedTag.value);dialog.value=false;}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function remove(key:string){try{await ElMessageBox.confirm("移除后，使用该公钥的主机将无法通过身份校验。","移除主机公钥",{confirmButtonText:"移除",cancelButtonText:"取消",type:"warning"});busy.value=true;error.value="";await persist(keys.value.filter(k=>k!==key),props.etag);}catch(e){if(e!=="cancel"&&e!=="close")error.value=message(e);}finally{busy.value=false;}}
async function reload(){try{const r=await request<RemoteHost>(props.base);emit("saved",r.data,r.etag);error.value="";dialog.value=false;}catch(e){error.value=message(e);}}
useUnsaved(()=>dialog.value,()=>busy.value);
</script>
<template><section class="remote-host-section host-connection-settings"><div v-if="error&&!dialog" class="error-banner" role="alert">{{error}} <ElButton link @click="reload">重新加载</ElButton></div><div class="host-connection-settings-heading"><h2>受信任的主机公钥</h2><div class="remote-host-actions"><ElButton :disabled="busy" @click="manual">录入公钥</ElButton><ElButton :disabled="busy||!connection.enabled" :loading="busy" @click="probe">探测公钥</ElButton></div></div><p>通过服务器控制台或可信运维渠道核对后再信任。公钥不匹配时阻止认证。</p><div v-if="!keys.length" class="remote-host-empty">尚未配置受信任公钥</div><article v-for="key in keys" :key="key" class="ssh-host-key"><div><strong>{{key.split(' ')[0]}}</strong><p class="host-connection-technical-value">{{fingerprints[key]}}</p><details><summary>查看公共密钥</summary><pre>{{key}}</pre></details></div><ElButton :disabled="busy" link type="danger" @click="remove(key)">移除</ElButton></article>
<ElDialog v-model="dialog" :title="probing?'核对主机公钥':'录入主机公钥'" width="min(600px,96vw)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy"><div v-if="error" class="error-banner" role="alert">{{error}} <ElButton link :disabled="busy" @click="reload">重新加载</ElButton></div><div class="remote-host-form"><p>{{connection.config?.host}}:{{connection.config?.port}}</p><p v-if="fingerprint" class="ssh-fingerprint">{{fingerprint}}</p><label>OpenSSH 公钥<ElInput v-model="candidate" type="textarea" :rows="5" maxlength="8192" :readonly="probing" :disabled="busy" @input="confirmed=false"/></label><ElCheckbox v-model="confirmed" :disabled="busy">我已通过可信来源核对，确认这是目标主机的公钥</ElCheckbox><p>新公钥会加入信任列表；轮换完成后可移除旧公钥。</p></div><template #footer><ElButton :disabled="busy" @click="dialog=false">取消</ElButton><ElButton type="primary" :disabled="!confirmed" :loading="busy" @click="save">信任此公钥</ElButton></template></ElDialog></section></template>
<style scoped>.ssh-host-key{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;padding:20px 0;border-top:1px solid var(--border)}.ssh-host-key>div{min-width:0}.ssh-host-key pre,.ssh-fingerprint{white-space:pre-wrap;overflow-wrap:anywhere}.ssh-host-key summary{cursor:pointer;color:var(--text-muted)}</style>
